/* ==== §1   Foundation =============================================== */
typedef uint8_t  u8;
typedef uint16_t u16;
typedef uint32_t u32;
typedef uint64_t u64;
typedef int32_t  i32;
typedef int64_t  i64;
typedef          __int128 i128;
typedef unsigned __int128 u128;

enum {Bits_Per_Unit = 8};
typedef enum {
  Width_1   = 1,  Width_8     = 8,  Width_16     = 16, Width_32 = 32, Width_64 = 64, Width_128 = 128,
  Width_Ptr = 64, Width_Float = 32, Width_Double = 64
} Bit_Width;
typedef enum {
  Ada_Short_Short_Integer_Bits = Width_8,
  Ada_Short_Integer_Bits       = Width_16,
  Ada_Integer_Bits             = Width_32,
  Ada_Long_Integer_Bits        = Width_64,
  Ada_Widest_Integer_Bits      = Ada_Long_Integer_Bits
} Ada_Integer_Width;
enum {
  Default_Size_Bits   = Ada_Integer_Bits,
  Default_Size_Bytes  = Ada_Integer_Bits / Bits_Per_Unit,
  Default_Align_Bytes = Default_Size_Bytes
};

enum { Target_Max_Mantissa = 31 };

u64 To_Bits    (u64 bytes) {return bytes * Bits_Per_Unit;}
u64 To_Bytes   (u64 bits)  {return (bits + Bits_Per_Unit - 1) / Bits_Per_Unit;}

