#define TASKING_BYTES(first, count) \
  ((((unsigned __int128) 1 << (count)) - 1) << (first))

_Static_assert (POINTER_ALLOC_SIZE == 8,
  "the tasking record layouts are written for an eight-byte pointer");

#define TASK_CONTROL_BLOCK_OFFSET_BODY_FUNCTION                   0
#define TASK_CONTROL_BLOCK_OFFSET_PARENT_FRAME                    8
#define TASK_CONTROL_BLOCK_OFFSET_THREAD_IDENTIFIER              16
#define TASK_CONTROL_BLOCK_OFFSET_COMPLETED                      24
#define TASK_CONTROL_BLOCK_OFFSET_MASTER_RECORD                  32
#define TASK_CONTROL_BLOCK_OFFSET_RENDEZVOUS_QUEUE_HEAD          40
#define TASK_CONTROL_BLOCK_OFFSET_ACCEPTING_ENTRY_INDEX          48
#define TASK_CONTROL_BLOCK_OFFSET_ACTIVATION_STATE               56
#define TASK_CONTROL_BLOCK_OFFSET_TERMINATED                     57
#define TASK_CONTROL_BLOCK_OFFSET_AWAITING_TERMINATE_ALTERNATIVE 58
#define TASK_CONTROL_BLOCK_OFFSET_PASSIVE                        59
#define TASK_CONTROL_BLOCK_OFFSET_ABORT_PENDING                  61
#define TASK_CONTROL_BLOCK_OFFSET_OWNED_MASTER_RECORDS           64
#define TASK_CONTROL_BLOCK_OFFSET_PENDING_RENDEZVOUS             72
#define TASK_CONTROL_BLOCK_OFFSET_OPEN_ENTRY_LIST                80
#define TASK_CONTROL_BLOCK_OFFSET_SERVED_RENDEZVOUS_LIST         88
#define TASK_CONTROL_BLOCK_SIZE                                  96

#define TASK_CONTROL_BLOCK_FIELD_LIST(X) \
    \
  X (BODY_FUNCTION,                   POINTER_ALLOC_SIZE) \
  X (PARENT_FRAME,                    POINTER_ALLOC_SIZE) \
  X (THREAD_IDENTIFIER,               POINTER_ALLOC_SIZE) \
  X (COMPLETED,                       1) \
  X (MASTER_RECORD,                   POINTER_ALLOC_SIZE) \
  X (RENDEZVOUS_QUEUE_HEAD,           POINTER_ALLOC_SIZE) \
  X (ACCEPTING_ENTRY_INDEX,           8) \
  X (ACTIVATION_STATE,                1) \
  X (TERMINATED,                      1) \
  X (AWAITING_TERMINATE_ALTERNATIVE,  1) \
  X (PASSIVE,                         1) \
  X (ABORT_PENDING,                   1) \
  X (OWNED_MASTER_RECORDS,            POINTER_ALLOC_SIZE) \
  X (PENDING_RENDEZVOUS,              POINTER_ALLOC_SIZE) \
  X (OPEN_ENTRY_LIST,                 POINTER_ALLOC_SIZE) \
  X (SERVED_RENDEZVOUS_LIST,          POINTER_ALLOC_SIZE)

#define TASK_CONTROL_BLOCK_UNUSED_BYTES \
  (TASKING_BYTES (25, 7) | TASKING_BYTES (60, 1) | TASKING_BYTES (62, 2))

#define TASK_FIELD(base, field) \
  "getelementptr i8, ptr " base ", i64 " \
  TEXT_OF (TASK_CONTROL_BLOCK_OFFSET_ ## field) \
  "  ; Task_Control_Block." #field

#define RENDEZVOUS_RECORD_OFFSET_TARGET_TASK          0
#define RENDEZVOUS_RECORD_OFFSET_ENTRY_INDEX          8
#define RENDEZVOUS_RECORD_OFFSET_PARAMETER_BLOCK     16
#define RENDEZVOUS_RECORD_OFFSET_COMPLETION_WORD     24
#define RENDEZVOUS_RECORD_OFFSET_NEXT                32
#define RENDEZVOUS_RECORD_OFFSET_EXCEPTION_IDENTITY  40
#define RENDEZVOUS_RECORD_SIZE                       48

#define RENDEZVOUS_RECORD_FIELD_LIST(X) \
    \
  X (TARGET_TASK,         POINTER_ALLOC_SIZE) \
  X (ENTRY_INDEX,         8) \
  X (PARAMETER_BLOCK,     POINTER_ALLOC_SIZE) \
  X (COMPLETION_WORD,     4) \
  X (NEXT,                POINTER_ALLOC_SIZE) \
  X (EXCEPTION_IDENTITY,  8)

#define RENDEZVOUS_RECORD_UNUSED_BYTES TASKING_BYTES (28, 4)

#define RENDEZVOUS_RECORD_FIELD(base, field) \
  "getelementptr i8, ptr " base ", i64 " \
  TEXT_OF (RENDEZVOUS_RECORD_OFFSET_ ## field) \
  "  ; Rendezvous_Record." #field

#define MASTER_RECORD_OFFSET_DEPENDENT_LIST_HEAD       0
#define MASTER_RECORD_OFFSET_ENCLOSING_MASTER          8
#define MASTER_RECORD_OFFSET_DONE_FLAG                16
#define MASTER_RECORD_OFFSET_OWNER_TASK_CONTROL_BLOCK 24
#define MASTER_RECORD_OFFSET_AWAKE_COUNT              32
#define MASTER_RECORD_OFFSET_SCOPE_IDENTITY           40
#define MASTER_RECORD_SIZE                            48

#define MASTER_RECORD_FIELD_LIST(X) \
    \
  X (DEPENDENT_LIST_HEAD,        POINTER_ALLOC_SIZE) \
  X (ENCLOSING_MASTER,           POINTER_ALLOC_SIZE) \
  X (DONE_FLAG,                  POINTER_ALLOC_SIZE) \
  X (OWNER_TASK_CONTROL_BLOCK,   POINTER_ALLOC_SIZE) \
  X (AWAKE_COUNT,                8) \
  X (SCOPE_IDENTITY,             8)

#define MASTER_RECORD_UNUSED_BYTES TASKING_BYTES (0, 0)

#define MASTER_RECORD_FIELD(base, field) \
  "getelementptr i8, ptr " base ", i64 " \
  TEXT_OF (MASTER_RECORD_OFFSET_ ## field) \
  "  ; Master_Record." #field

#define TASKING_LIST_NODE_OFFSET_ELEMENT  0
#define TASKING_LIST_NODE_OFFSET_NEXT     8
#define TASKING_LIST_NODE_SIZE           16

#define TASKING_LIST_NODE_FIELD_LIST(X) \
    \
  X (ELEMENT,  POINTER_ALLOC_SIZE) \
  X (NEXT,     POINTER_ALLOC_SIZE)

#define TASKING_LIST_NODE_UNUSED_BYTES TASKING_BYTES (0, 0)

#define TASKING_LIST_NODE_FIELD(base, field) \
  "getelementptr i8, ptr " base ", i64 " \
  TEXT_OF (TASKING_LIST_NODE_OFFSET_ ## field) \
  "  ; Tasking_List_Node." #field

#define TASKING_RECORD_LAYOUT_PINNED(record) \
  _Static_assert ( \
    (0 record ## _FIELD_LIST (record ## _EXTENT)) == \
    (TASKING_BYTES (0, record ## _SIZE) & ~record ## _UNUSED_BYTES), \
    "the " #record " field list, unused bytes and size no longer " \
    "describe the same record")

#define TASK_CONTROL_BLOCK_EXTENT(field, width) \
  | TASKING_BYTES (TASK_CONTROL_BLOCK_OFFSET_ ## field, width)
#define RENDEZVOUS_RECORD_EXTENT(field, width) \
  | TASKING_BYTES (RENDEZVOUS_RECORD_OFFSET_ ## field, width)
#define MASTER_RECORD_EXTENT(field, width) \
  | TASKING_BYTES (MASTER_RECORD_OFFSET_ ## field, width)
#define TASKING_LIST_NODE_EXTENT(field, width) \
  | TASKING_BYTES (TASKING_LIST_NODE_OFFSET_ ## field, width)

TASKING_RECORD_LAYOUT_PINNED (TASK_CONTROL_BLOCK);
TASKING_RECORD_LAYOUT_PINNED (RENDEZVOUS_RECORD);
TASKING_RECORD_LAYOUT_PINNED (MASTER_RECORD);
TASKING_RECORD_LAYOUT_PINNED (TASKING_LIST_NODE);

#undef TASK_CONTROL_BLOCK_EXTENT
#undef RENDEZVOUS_RECORD_EXTENT
#undef MASTER_RECORD_EXTENT
